package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();var st string;var end,next any;var pnd,lease,handoff,intents int;e=p.QueryRow(c,`select status,end_at,next_fire_at,(select count(*) from recording_jobs j where j.recording_id=407 and j.status='pending'),(select count(*) from recording_jobs j where j.recording_id=407 and j.status='leased' and j.lease_expires_at>now()),(select count(*) from recording_jobs j where j.recording_id=407 and j.handoff_until>now()),(select count(*) from recording_upload_intents u where u.recording_id=407 and u.status='pending' and u.expires_at>now()) from recordings where id=407`).Scan(&st,&end,&next,&pnd,&lease,&handoff,&intents);fmt.Printf("status=%s end=%v next=%v pending=%d leased=%d handoff=%d intents=%d err=%v\n",st,end,next,pnd,lease,handoff,intents,e)}
